const componentNames = navItems.map(i=>i.id)

const REPO_OWNER = "jasonpereirax"
const REPO_NAME = "gauge-design-system"

function InsightsPage() {
  const [components, setComponents] = useState<any[]>([])
  const [stats, setStats] = useState<any>({ commits: null, releases: null, prs: null, contributors: null, dependents: null, lastDeploy: null })
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string|null>(null)

  useEffect(() => {
    let cancelled = false
    async function load() {
      try {
        // Read components.json (own data)
        const cj = await fetch("/components.json").then(r => r.ok ? r.json() : null).catch(()=>null)
        if (!cancelled && cj?.components) setComponents(cj.components)

        const base = "https://api.github.com/repos/" + REPO_OWNER + "/" + REPO_NAME
        const headers = { "Accept": "application/vnd.github+json" }

        const [commits, releases, prs, contribs] = await Promise.all([
          fetch(base + "/commits?per_page=100", { headers }).then(r=>r.ok?r.json():[]).catch(()=>[]),
          fetch(base + "/releases?per_page=100", { headers }).then(r=>r.ok?r.json():[]).catch(()=>[]),
          fetch(base + "/pulls?state=all&per_page=100", { headers }).then(r=>r.ok?r.json():[]).catch(()=>[]),
          fetch(base + "/contributors?per_page=100", { headers }).then(r=>r.ok?r.json():[]).catch(()=>[])
        ])

        if (cancelled) return
        setStats({
          commits: Array.isArray(commits) ? commits.length : 0,
          releases: Array.isArray(releases) ? releases.length : 0,
          prs: Array.isArray(prs) ? prs.length : 0,
          contributors: Array.isArray(contribs) ? contribs.length : 0,
          dependents: null,
          lastDeploy: Array.isArray(commits) && commits[0] ? commits[0].commit?.author?.date : null,
          recentCommits: Array.isArray(commits) ? commits.slice(0,8) : []
        })
      } catch(e:any) {
        if (!cancelled) setError(e.message || String(e))
      } finally {
        if (!cancelled) setLoading(false)
      }
    }
    load()
    return () => { cancelled = true }
  }, [])

  const byCategory: Record<string,any[]> = {}
  components.forEach(c => { (byCategory[c.category||"Components"] = byCategory[c.category||"Components"]||[]).push(c) })

  const byStatus: Record<string,number> = {}
  components.forEach(c => { byStatus[c.status||"stable"] = (byStatus[c.status||"stable"]||0) + 1 })

  return (
    <div>
      <div style={{ borderBottom:"1px solid #e4e4e7",paddingBottom:"24px",marginBottom:"28px" }}>
        <h1 style={{ fontSize:"26px",fontWeight:700,letterSpacing:"-0.02em",margin:"0 0 6px" }}>Insights</h1>
        <p style={{ margin:0,fontSize:"14px",color:"#71717a" }}>Visibilidade do uso e evolução do design system.</p>
      </div>

      {error && <div style={{ padding:"12px 14px",background:"#fef2f2",border:"1px solid #fecaca",borderRadius:"8px",color:"#991b1b",fontSize:"13px",marginBottom:"20px" }}>Erro ao carregar dados: {error}</div>}

      <div style={{ display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(140px,1fr))",gap:"12px",marginBottom:"32px" }}>
        {[
          { label:"Componentes", value: components.length, hint: components.length===1?"componente":"componentes" },
          { label:"Categorias", value: Object.keys(byCategory).length, hint:"agrupamentos" },
          { label:"Releases", value: stats.releases ?? "—", hint:"versões publicadas" },
          { label:"Pull Requests", value: stats.prs ?? "—", hint:"abertos + fechados" },
          { label:"Commits", value: stats.commits ?? "—", hint:"recentes (≤100)" },
          { label:"Contribuidores", value: stats.contributors ?? "—", hint:"únicos" }
        ].map((kpi,i) => (
          <div key={i} style={{ padding:"14px 16px",border:"1px solid #e4e4e7",borderRadius:"10px",background:"#fff" }}>
            <div style={{ fontSize:"11px",fontWeight:600,color:"#71717a",textTransform:"uppercase",letterSpacing:"0.06em",marginBottom:"6px" }}>{kpi.label}</div>
            <div style={{ fontSize:"22px",fontWeight:700,color:"#18181b",lineHeight:1 }}>{loading && kpi.value==="—"?"…":kpi.value}</div>
            <div style={{ fontSize:"11px",color:"#a1a1aa",marginTop:"4px" }}>{kpi.hint}</div>
          </div>
        ))}
      </div>

      {Object.keys(byStatus).length > 0 && (
        <div style={{ marginBottom:"32px" }}>
          <h2 style={{ fontSize:"13px",fontWeight:600,color:"#71717a",textTransform:"uppercase",letterSpacing:"0.07em",marginBottom:"12px" }}>Status dos componentes</h2>
          <div style={{ display:"flex",gap:"8px",flexWrap:"wrap" }}>
            {Object.entries(byStatus).map(([s,n]) => (
              <div key={s} style={{ padding:"8px 14px",border:"1px solid #e4e4e7",borderRadius:"8px",background:"#fafafa",display:"flex",alignItems:"center",gap:"8px" }}>
                <StatusBadge status={s as Status} />
                <span style={{ fontSize:"15px",fontWeight:700,color:"#18181b" }}>{n}</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {Object.keys(byCategory).length > 0 && (
        <div style={{ marginBottom:"32px" }}>
          <h2 style={{ fontSize:"13px",fontWeight:600,color:"#71717a",textTransform:"uppercase",letterSpacing:"0.07em",marginBottom:"12px" }}>Componentes por categoria</h2>
          <div style={{ border:"1px solid #e4e4e7",borderRadius:"10px",overflow:"hidden",background:"#fff" }}>
            <table style={{ width:"100%",borderCollapse:"collapse",fontSize:"13px" }}>
              <thead>
                <tr style={{ background:"#fafafa",borderBottom:"1px solid #e4e4e7" }}>
                  {["Categoria","Componentes","Última atualização"].map(h => <th key={h} style={{ textAlign:"left",padding:"9px 14px",fontWeight:600,color:"#52525b",fontSize:"11px",textTransform:"uppercase",letterSpacing:"0.06em" }}>{h}</th>)}
                </tr>
              </thead>
              <tbody>
                {Object.entries(byCategory).map(([cat,comps]:[string,any]) => {
                  const latest = comps.reduce((a:any,b:any) => !a||(b.lastUpdated||"")>(a.lastUpdated||"")?b:a, null)
                  return (
                    <tr key={cat} style={{ borderBottom:"1px solid #f4f4f5" }}>
                      <td style={{ padding:"10px 14px",fontWeight:600,color:"#18181b" }}>{cat}</td>
                      <td style={{ padding:"10px 14px" }}>
                        <div style={{ display:"flex",flexWrap:"wrap",gap:"4px" }}>
                          {comps.map((c:any) => (
                            <button key={c.name} onClick={()=>{window.location.hash=c.safeName||c.name.replace(/[^a-zA-Z0-9]/g,"")}}
                              style={{ fontSize:"11px",padding:"2px 8px",borderRadius:"4px",background:"#f4f4f5",color:"#18181b",border:"1px solid #e4e4e7",cursor:"pointer",fontFamily:"monospace" }}>
                              {c.name}
                              {c.version && <span style={{color:"#a1a1aa",marginLeft:"4px"}}>v{c.version}</span>}
                            </button>
                          ))}
                        </div>
                      </td>
                      <td style={{ padding:"10px 14px",fontSize:"12px",color:"#71717a",whiteSpace:"nowrap" }}>
                        {latest?.lastUpdated ? new Date(latest.lastUpdated).toLocaleDateString("pt-BR") : "—"}
                      </td>
                    </tr>
                  )
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {stats.recentCommits && stats.recentCommits.length > 0 && (
        <div>
          <h2 style={{ fontSize:"13px",fontWeight:600,color:"#71717a",textTransform:"uppercase",letterSpacing:"0.07em",marginBottom:"12px" }}>Atividade recente</h2>
          <div style={{ border:"1px solid #e4e4e7",borderRadius:"10px",overflow:"hidden",background:"#fff" }}>
            {stats.recentCommits.map((c:any,i:number) => (
              <a key={c.sha} href={c.html_url} target="_blank" rel="noopener noreferrer"
                 style={{ display:"flex",alignItems:"center",gap:"12px",padding:"10px 14px",borderBottom: i<stats.recentCommits.length-1?"1px solid #f4f4f5":"none",textDecoration:"none",color:"inherit" }}>
                {c.author?.avatar_url && <img src={c.author.avatar_url} alt="" style={{width:"24px",height:"24px",borderRadius:"50%"}} />}
                <div style={{ flex:1,minWidth:0 }}>
                  <div style={{ fontSize:"13px",color:"#18181b",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap" }}>{c.commit.message.split("\n")[0]}</div>
                  <div style={{ fontSize:"11px",color:"#a1a1aa" }}>
                    {c.commit.author?.name} · {new Date(c.commit.author?.date).toLocaleDateString("pt-BR")}
                  </div>
                </div>
                <span style={{ fontSize:"10px",fontFamily:"monospace",color:"#a1a1aa" }}>{c.sha?.slice(0,7)}</span>
              </a>
            ))}
          </div>
        </div>
      )}

      <div style={{ marginTop:"32px",padding:"12px 14px",background:"#fafafa",borderRadius:"8px",fontSize:"12px",color:"#71717a",lineHeight:1.5 }}>
        Dados do GitHub atualizados em tempo real via API pública. Para telemetria de uso em produção (URLs consumindo o pacote), seria necessário adicionar um endpoint de coleta — disponível em fase futura.
      </div>
    </div>
  )
}

